  authUnlockMind: ['Desbloquear mente', 'Desbloquear mente', 'Unlock mind', 'Déverrouiller l’esprit'],
  authMnemonicPlaceholder: ['12 palavras da tua chave soberana', '12 palavras da sua chave soberana', '12 words of your sovereign key', '12 mots de votre clé souveraine'],

