  indexPublishStatus_published: ['{count} memória(s) publicadas. Confirma a vista atual antes de outro lote.', '{count} memória(s) publicadas. Confira a vista atual antes de outro lote.', '{count} memories published. Check the current view before another batch.', '{count} mémoires publiées. Vérifiez la vue actuelle avant un autre lot.'],
