  indexPublishStatus_failed: ['Não foi possível concluir. Confirma os pedidos pendentes antes de repetir.', 'Não foi possível concluir. Confira os pedidos pendentes antes de repetir.', 'Could not finish. Check pending requests before trying again.', 'Impossible de terminer. Vérifiez les demandes en attente avant de réessayer.'],
  indexPublishStatus_baseline: ['A memória ou o acesso mudou, ou falta preparação. Atualiza a vista e prepara novamente.', 'A memória ou o acesso mudou, ou falta preparação. Atualize a vista e prepare novamente.', 'The memory or access changed, or preparation is missing. Refresh the view and prepare again.', 'La mémoire ou l’accès a changé, ou la préparation manque. Actualisez la vue et préparez à nouveau.'],
