  reindexStatus_prepared: ['Preparação terminada. O novo índice ainda não está ativo.', 'Preparação concluída. O novo índice ainda não está ativo.', 'Preparation finished. The new index is not active yet.', 'Préparation terminée. Le nouvel index n’est pas encore actif.'],
