  settingsAiProviderUnavailable: ['Por configurar', 'Por configurar', 'Not configured', 'À configurer'],
  settingsAiLegacySecretUnused: ['Esta chave local antiga não é usada pela geração no servidor. Podes removê-la deste dispositivo.', 'Esta chave local antiga não é usada pela geração no servidor. Você pode removê-la deste dispositivo.', 'This legacy local key is not used for server generation. You can remove it from this device.', 'Cette ancienne clé locale n’est pas utilisée pour la génération sur le serveur. Vous pouvez la supprimer de cet appareil.'],
  settingsAiProviderUnavailableHint: ['Este fornecedor não está ativo neste lançamento. Seleciona um fornecedor disponível para gerar conteúdo.', 'Este fornecedor não está ativo neste lançamento. Selecione um fornecedor disponível para gerar conteúdo.', 'This provider is not enabled for this release. Select an available provider to generate content.', 'Ce fournisseur n’est pas actif pour cette version. Sélectionnez un fournisseur disponible pour générer du contenu.'],
