  teamDestHint: ['As memórias desta equipa podem ser lidas; a escrita fica suspensa até existir rotação segura de chaves.', 'As memórias desta equipe podem ser lidas; a escrita fica suspensa até existir rotação segura de chaves.', 'Existing team memories can be read; writes are paused until secure key rotation is available.', 'Les mémoires d’équipe existantes peuvent être lues ; les écritures sont suspendues jusqu’à la rotation sécurisée des clés.'],
  teamEmpty: ['A criação de equipas está suspensa durante o lançamento pessoal.', 'A criação de equipes está suspensa durante o lançamento pessoal.', 'Team creation is paused during the personal release.', 'La création d’équipes est suspendue pendant le lancement personnel.'],
  teamCreated: ['Equipa “{name}” criada. A teamKey ficou só no teu wrap RSA.', 'Equipe “{name}” criada. A teamKey ficou só no seu wrap RSA.', 'Team “{name}” created. The teamKey stayed only in your RSA wrap.', 'Équipe « {name} » créée. La teamKey n’est restée que dans votre enveloppe RSA.'],
